import{z as o,x as s,o as A,c as d,q as r,j as i,D as a,d as e,s as l,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"粒子滤波","description":"","frontmatter":{"title":"粒子滤波","date":"2026-09-27T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/particle-filter.md","filePath":"quant/particle-filter.md","lastUpdated":1791413859000}'),m={name:"quant/particle-filter.md"};function D(p,E,S,h,_,C){const B=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=r('<h1 id="粒子滤波" tabindex="-1">粒子滤波 <a class="header-anchor" href="#粒子滤波" aria-label="Permalink to &quot;粒子滤波&quot;">​</a></h1><div class="epigraph"><p>状态不可观测、观测充满噪声时，别再硬猜单点估计——用一群带权粒子把整个后验分布搬进内存，让分布随数据逐笔滚动。</p><footer>—— 据 Gordon, Salmond and Smith, 1993；Doucet, de Freitas and Gordon, 2001</footer></div><p><a href="/quant/ed-case-map">上一课</a>把事件策略收束成一张谱系表，本课开新单元：状态估计。市场里真正关心的量——公允价差、波动率水平、当前 regime——都不在行情里，只能从带噪价格反推。线性高斯世界有 Kalman 滤波给精确解；转移或观测方程一旦非线性、噪声一旦厚尾，它只剩近似。粒子滤波换掉的是解的形态：不再解析地写下后验，而是用随机粒子群逼近它。这不是「更好用的 Kalman」，是表示层的更换。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>状态空间模型两行：状态按 \\(x_t=f(x_{t-1})+\\eta_t\\) 演化，观测按 \\(y_t=g(x_t)+\\epsilon_t\\) 到来。Kalman 滤波只在 \\(f\\) 与 \\(g\\) 线性且噪声高斯时给出精确后验。跳变、厚尾、阈值触发、regime 切换，任何一条都把它打回近似。<a href="/quant/brownian-motion-paths">布朗运动</a>那课的维纳噪声是高斯驱动的起点，现实价格里塞满了不服从它的东西。本课写 bootstrap 滤波的完整循环与失效模式，不重推 Kalman 增益，也不展开 EM 参数估计的推导。</p><p><span class="marginnote">术语翻译：粒子就是「一份对当前状态的候选答案」加一个置信权重——2000 个粒子等于同时维护 2000 个平行世界，各自有一条状态路径，权重记录它与观测的吻合度。滤波（filtering）指只用截至 \\(t\\) 的数据估 \\(t\\) 时刻状态，区别于用未来数据的平滑（smoothing）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>bootstrap 滤波四步，随每个观测滚动一轮：按转移密度撒粒子，按观测似然配权重，归一化出后验估计，权重塌缩时重采样。<span class="marginnote">数字实例：取 \\(N=2000\\) 个粒子，重采样阈值常设 \\(N/10\\)。某步算出有效样本量 \\(\\mathrm{ESS}=1/\\sum_i w_i^2=260\\gt 200\\)，暂不动；下一步强观测把 ESS 打到 \\(150\\lt 200\\)，触发重采样——按权重放回抽样 2000 个，权重重置为均匀。ESS 从 2000 掉到两位数往往只需几次集中观测，塌缩来得比直觉快。</span></p>',8)),(A(),i(n,null,{default:a(()=>[l(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20INIT%5B%22%E5%88%9D%E5%A7%8B%E5%8C%96%20N%20%E4%B8%AA%E7%B2%92%E5%AD%90%22%5D%20--%3E%20PROP%5B%22%E6%8C%89%E8%BD%AC%E7%A7%BB%E5%AF%86%E5%BA%A6%E4%BC%A0%E6%92%AD%E6%AF%8F%E4%B8%AA%E7%B2%92%E5%AD%90%22%5D%0A%20%20PROP%20--%3E%20LIKE%5B%22%E6%8C%89%E8%A7%82%E6%B5%8B%E4%BC%BC%E7%84%B6%E6%9B%B4%E6%96%B0%E6%9D%83%E9%87%8D%22%5D%0A%20%20LIKE%20--%3E%20NORM%5B%22%E5%BD%92%E4%B8%80%E5%8C%96%E5%B9%B6%E8%BE%93%E5%87%BA%E5%90%8E%E9%AA%8C%E4%BC%B0%E8%AE%A1%22%5D%0A%20%20NORM%20--%3E%20ESS%5B%22%E8%AE%A1%E7%AE%97%E6%9C%89%E6%95%88%E6%A0%B7%E6%9C%AC%E9%87%8F%22%5D%0A%20%20ESS%20--%3E%7C%22%E4%BD%8E%E4%BA%8E%E9%98%88%E5%80%BC%22%7C%20RES%5B%22%E9%87%8D%E9%87%87%E6%A0%B7%EF%BC%9A%E9%AB%98%E6%9D%83%E7%B2%92%E5%AD%90%E5%A4%8D%E5%88%B6%22%5D%0A%20%20ESS%20--%3E%7C%22%E5%90%A6%E5%88%99%22%7C%20NEXT%5B%22%E7%9B%B4%E6%8E%A5%E8%BF%9B%E5%85%A5%E4%B8%8B%E4%B8%80%E8%BD%AE%22%5D%0A%20%20RES%20--%3E%20NEXT%0A%20%20NEXT%20--%3E%20PROP%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,[e("有效性来自大数定律：粒子经验分布以 \\(1/\\sqrt{N}\\) 的速度收敛到真后验，权重不是拍脑袋的分数，而是精确的似然比 \\(p(y_t\\mid x_t^i)\\)。它对 \\(f\\) 与 \\(g\\) 的形态毫无要求——跳变函数、混合高斯、带阈值的观测照收，这是解析滤波器做不到的。代价藏在重采样里：复制活粒子、淘汰死粒子，粒子多样性被削，之后的差异全靠转移噪声重新长出来——粒子贫化。"),t("span",{class:"marginnote"},"常见误区：把重采样后的粒子当独立样本。错在「权重均匀化」这一步——2000 个粒子此刻可能只有 150 个祖先，它们是复制品不是新证据；方差被系统性低估，置信区间随之虚窄。补救靠扰动粗糙化或正则化采样，不是靠再加粒子数。")],-1)),(A(),i(n,null,{default:a(()=>[l(B,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBS%5B%22%E6%96%B0%E8%A7%82%E6%B5%8B%E5%88%B0%E6%9D%A5%22%5D%20--%3E%20Q%7B%22ESS%20%E5%8D%A0%20N%20%E7%9A%84%E6%AF%94%E4%BE%8B%E5%A4%9F%E9%AB%98%E5%90%97%22%7D%0A%20%20Q%20--%3E%7C%22%E5%A4%9F%E9%AB%98%22%7C%20KEEP%5B%22%E5%B8%A6%E6%9D%83%E4%BF%9D%E7%95%99%EF%BC%9A%E4%BF%A1%E6%81%AF%E7%BB%A7%E7%BB%AD%E7%B4%AF%E7%A7%AF%22%5D%0A%20%20Q%20--%3E%7C%22%E4%B8%8D%E5%A4%9F%22%7C%20RES%5B%22%E9%87%8D%E9%87%87%E6%A0%B7%EF%BC%9A%E5%A4%8D%E5%88%B6%E9%AB%98%E6%9D%83%E7%B2%92%E5%AD%90%22%5D%0A%20%20RES%20--%3E%20JAG%5B%22%E5%8A%A0%E6%89%B0%E5%8A%A8%E6%81%A2%E5%A4%8D%E5%A4%9A%E6%A0%B7%E6%80%A7%22%5D%0A%20%20KEEP%20--%3E%20NEXT%5B%22%E8%BF%9B%E5%85%A5%E4%B8%8B%E4%B8%80%E8%BD%AE%E4%BC%A0%E6%92%AD%22%5D%0A%20%20JAG%20--%3E%20NEXT%0A%20%20NEXT%20--%3E%20GOOD%5B%22%E5%90%8E%E9%AA%8C%E5%BD%A2%E7%8A%B6%E4%BB%8D%E8%A2%AB%E8%A6%86%E7%9B%96%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>维度是硬墙：粒子要覆盖的体积随状态维度指数膨胀，十维以上的状态基本告别朴素粒子滤波——不是算得慢，是同等预算下后验根本没被覆盖。实时性另算一笔账：每个观测要做 \\(N\\) 次转移加 \\(N\\) 次似然求值。线性部分能剥离时用 Rao-Blackwellized 变体省预算，推导复杂度则直线上升。温和非线性、后验近似单峰的场景，下一课的无迹卡尔曼用确定性采样给出便宜一个量级的方案——粒子滤波留给它啃不动的厚尾与多峰。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>粒子滤波用带权粒子群逼近后验分布，对非线性和非高斯一视同仁。</li><li>循环四步：传播、加权、归一、按 ESS 判定重采样。</li><li>重采样治塌缩也引贫化，复制品不是新信息。</li><li>维度与算力是边界；温和非线性优先考虑确定性采样。</li><li>出处：Gordon, Salmond and Smith, <em>IEE Proceedings F</em>, 1993；Doucet, de Freitas and Gordon, <em>Sequential Monte Carlo Methods in Practice</em>, 2001；Liu and Chen, <em>JASA</em>, 1998。</li></ul>',4))])}const f=o(m,[["render",D]]);export{u as __pageData,f as default};
